L["|cffe8e0a0sent to|r |cffffffff%s|r"] = "|cffe8e0a0enviado a|r |cffffffff%s|r"
L["|cffe8e0a0sent to|r |cffffffffthem|r"] = "|cffe8e0a0enviado a|r |cffffffffesa persona|r"
L["|cff8ce88cbuffed|r |cffffffff%s|r"] = "|cff8ce88cdado a|r |cffffffff%s|r"
L["|cff8ce88cbuffed|r |cffffffffthem|r"] = "|cff8ce88cdado a|r |cffffffffesa persona|r"
L["the game confirmed it"] = "el juego lo confirmó"
L["still armed by the fight"] = "sigue preparado"
L["nothing to buff"] = "nadie a quien ofrecer"
L["nothing this character can cast -- a press still casts what the fight froze"] = "este personaje no puede lanzar nada -- pulsar aún lanza lo que congeló el combate"
L["nothing this character can cast -- nothing armed, and the panel cannot go"] = "este personaje no puede lanzar nada -- nada preparado y el panel no se puede ocultar"
L["preview off -- timed out."] = "vista previa desactivada -- se acabó el tiempo."
L["preview off -- somebody real turned up."] = "vista previa desactivada -- apareció alguien real."
L["Someone %d"] = "Alguien %d"
L["switched off -- a press still casts what the fight froze"] = "desactivado -- pulsar aún lanza lo que congeló el combate"
L["switched off -- nothing armed, and the panel cannot go"] = "desactivado -- nada preparado y el panel no se puede ocultar"
L["Drag to move"] = "Arrastra para mover"
L["not buffing while unlocked"] = "desbloqueado: no lanza nada"
L["unlocked -- a press still casts what the fight froze"] = "desbloqueado -- pulsar aún lanza lo que congeló el combate"
L["unlocked -- nothing armed, and the panel cannot go"] = "desbloqueado -- nada preparado y el panel no se puede ocultar"
L["held -- in combat"] = "retenido -- en combate"
L["held -- a press still casts what the fight froze"] = "retenido -- pulsar aún lanza lo que congeló el combate"
L["held -- nothing armed, and the panel cannot go"] = "retenido -- nada preparado y el panel no se puede ocultar"
L["ready in %.1fs"] = "listo en %.1f s"
L["%s |cffffd100snoozed until %s|r"] = "%s |cffffd100en pausa hasta las %s|r"
L["%s |cffff8080off|r"] = "%s |cffff8080desactivado|r"
L["%s |cff80e0801 waiting|r"] = "%s |cff80e0801 esperando|r"
L["%s |cff80e080%d waiting|r"] = "%s |cff80e080%d esperando|r"
L["Automatic"] = "Automático"
L["%s |cff808080(not learned)|r"] = "%s |cff808080(sin aprender)|r"
L["%s |cff808080(mana users only)|r"] = "%s |cff808080(solo usuarios de maná)|r"
L["%s |cff808080(your group only)|r"] = "%s |cff808080(solo tu grupo)|r"
L["This character has nothing it can cast on another player."] = "Este personaje no tiene nada que pueda lanzar sobre otro jugador."
L["You have not learned any of these yet, so nobody will be offered anything."] = "Aún no aprendiste ninguno de estos, así que no se ofrecerá nada a nadie."
L["Automatic never offers %s -- nobody standing in a city wants it -- so nobody will be offered anything."] = "Automático nunca ofrece %s -- en una ciudad no le sirve a nadie -- así que no se ofrecerá nada a nadie."
L["Pin it in the dropdown above if you want it given out anyway."] = "Fija el hechizo en el desplegable de arriba si quieres ofrecerlo de todos modos."
L["Every spell you have learned is switched off, so nothing is offered until you switch one back on or learn one of the others."] = "Todos los hechizos que conoces están desactivados, así que no se ofrece nada hasta que vuelvas a activar uno o aprendas alguno de los demás."
L["Every spell below is switched off, so the prompt will never appear."] = "Todos los hechizos de abajo están desactivados, así que el aviso nunca aparecerá."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. |cffffd100Always offer|r does not check what they carry, so it can replace one of yours."] = "Tus bendiciones se reemplazan entre sí, así que Automático da solo la primera de %s que le sirva. |cffffd100Ofrecer siempre|r no comprueba lo que lleva, así que puede reemplazar una de las tuyas."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Where the game hides which blessing somebody carries, it can replace one of yours."] = "Tus bendiciones se reemplazan entre sí, así que Automático da solo la primera de %s que le sirva. Donde el juego oculta qué bendición lleva alguien, puede reemplazar una de las tuyas."
L["Your blessings replace one another, so Automatic gives only the first of %s that suits them. Anybody already carrying one of yours is left alone."] = "Tus bendiciones se reemplazan entre sí, así que Automático da solo la primera de %s que le sirva. A quien ya lleva una tuya no se le ofrece otra."
L["Automatic offers the first of these they are missing, in this order: %s."] = "Automático ofrece el primero de estos que le falte, en este orden: %s."
L["Where the game will not say what somebody is carrying, it moves down the list each time instead of offering the same one over and over."] = "Donde el juego no dice qué lleva alguien, avanza por la lista cada vez en lugar de ofrecer el mismo una y otra vez."
L["Only |cffffffff%s|r is offered, to everybody, whatever else they are missing. The per-spell switches come back with Automatic."] = "Solo se ofrece |cffffffff%s|r, a todo el mundo, le falte lo que le falte. Las casillas de cada hechizo vuelven a aplicarse con Automático."
L["You have pinned %s, which you have not learned."] = "Tienes fijado %s, un hechizo que aún no aprendiste."
L["Nothing will be offered to anybody until you learn it or switch back to Automatic."] = "No se ofrecerá nada a nadie hasta que lo aprendas o vuelvas a Automático."
L["Switched off, this one is never offered to anybody and Automatic walks straight past it. Everything else carries on as before."] = "Si lo desactivas, este hechizo no se ofrece nunca a nadie y Automático pasa de largo. Todo lo demás sigue igual."
L["Who to buff"] = "A quién ofrecer"
L["Buffs"] = "Beneficios"
L["Buff to cast"] = "Beneficio que lanzar"
L["Sources"] = "Candidatos"
L["Nothing below is switched on, so the prompt will never appear."] = "No hay nada activado abajo, así que el aviso nunca aparecerá."
L["People who buffed me"] = "Quienes me dieron un beneficio"
L["Watch for buffs cast on you and offer to return them. What you cast reaches only your own party -- in a raid, your own subgroup -- so somebody outside it is offered once they join."] = "Vigila los beneficios que te lanzan y ofrece devolverlos. Lo que lanzas solo llega a tu propio grupo -- en una banda, tu propio subgrupo -- así que a quien esté fuera se le ofrece cuando se una."
L["Watch for buffs cast on you and offer to return them. What you cast reaches your group only, so somebody outside it is offered once they join."] = "Vigila los beneficios que te lanzan y ofrece devolverlos. Lo que lanzas solo llega a tu grupo, así que a quien esté fuera se le ofrece cuando se una."
L["Watch for buffs cast on you and offer to return them. Works on strangers who are not in your group."] = "Vigila los beneficios que te lanzan y ofrece devolverlos. Funciona con desconocidos que no están en tu grupo."
L["Only count real class buffs"] = "Contar solo los verdaderos beneficios de clase"
L["A shield, a heal-over-time or a trinket proc is not a favour owed. Leave this on unless you want every incoming aura to count."] = "Un escudo, una sanación periódica o la activación de un abalorio no son un favor pendiente. Déjalo activado salvo que quieras que cuente cualquier aura que recibas."
L["My party and raid"] = "Mi grupo y banda"
L["Nearby players not in my group"] = "Jugadores cercanos fuera de mi grupo"
L["Offer passers-by who are missing the buff. Seen through nameplates, your target, your focus and your mouseover."] = "Ofrece el beneficio a los transeúntes que no lo tienen. Se detectan por las placas de nombre, tu objetivo, tu foco y lo que tengas bajo el cursor."
L["Everything you can offer is cast on yourself and heard by your party, so there is nothing to give a passer-by."] = "Todo lo que puedes ofrecer se lanza sobre ti y lo oye tu grupo, así que no hay nada que dar a un transeúnte."
L["People who ask me for it"] = "Quienes me piden un beneficio"
L["For a minute, offer your buff to somebody who asks for it in /say, /yell, group chat or a whisper -- \"int pls\", \"fort?\", \"buffs please\"."] = "Durante un minuto, ofrece tu beneficio a quien lo pida en /say, /yell, el chat de tu grupo o un susurro -- \"int pls\", \"fort?\", \"buffs please\"."
L["Only short requests count, and in a fight only whispers. Nothing is said back to them."] = "Solo cuentan las peticiones cortas, y en combate solo los susurros. No se les responde nada."
L["Off at first: reading chat is guesswork, so now and then somebody only talking about a buff is offered one."] = "Viene desactivado de forma predeterminada: leer el chat es adivinar, así que de vez en cuando se le ofrece un beneficio a alguien que solo estaba hablando de uno."
L["Wording: asked for it"] = "Texto: lo pidió"
L["The prompt's second line for somebody who asked for the buff in chat."] = "La segunda línea del aviso para quien pidió el beneficio en el chat."
L["Who comes first"] = "Quién va primero"
L["Whoever I have targeted comes first"] = "Mi objetivo va primero"
L["Your target outranks a favour owed, but only when the game can read that they are missing the buff."] = "Tu objetivo va por delante de un favor pendiente, pero solo cuando el juego puede ver que le falta el beneficio."
L["Not while |cffffd100If they already have the buff|r is set to Always offer, under When, since nothing is read then."] = "No se aplica mientras |cffffd100Si ya tiene el beneficio|r esté en Ofrecer siempre, en la pestaña Cuándo, porque entonces no se lee nada."
L["Mouseover is left out: the prompt would flicker as the cursor crossed the screen."] = "Lo que tengas bajo el cursor se deja fuera: el aviso parpadearía al cruzar el cursor la pantalla."
L["My friends and guildmates come before the others"] = "Mis amigos y compañeros de hermandad van antes que los demás"
L["A friend or guildmate goes ahead of the other passers-by, or of the rest of your group. It only changes the order; nobody is added or left out."] = "Un amigo o compañero de hermandad va antes que los demás transeúntes, o que el resto de tu grupo. Solo cambia el orden; no se añade ni se deja fuera a nadie."
L["Friends include Battle.net friends. When the game will not say whether somebody is a friend, they are ranked like anybody else."] = "Los amigos incluyen a los amigos de Battle.net. Cuando el juego no dice si alguien está entre tus amigos, se ordena como cualquiera."
L["Who to skip"] = "A quién omitir"
L["Mana-only buffs such as Arcane Intellect, Wisdom and Divine Spirit are wasted on warriors and rogues."] = "Los beneficios que solo sirven con maná, como Intelecto Arcano, Sabiduría y Espíritu divino, se desperdician en guerreros y pícaros."
L["Hide players known to be out of range"] = "Ocultar jugadores que se sabe que están fuera de alcance"
L["When the game will not tell us the range -- common on this client -- they are still offered."] = "Cuando el juego no nos dice si están al alcance -- algo habitual en este cliente -- se les sigue ofreciendo."
L["How near a passer-by has to be"] = "A qué distancia debe estar un transeúnte"
L["Being in range is not the same as being near: Arcane Intellect and its like reach about thirty yards, which in a city is everybody on the screen."] = "Estar al alcance no es lo mismo que estar cerca: Intelecto Arcano y similares llegan a unos treinta metros, que en una ciudad es toda la gente que ves en pantalla."
L["|cffffd100Anywhere I can cast|r -- about thirty yards, as it was."] = "|cffffd100Hasta donde pueda lanzar|r -- unos treinta metros, como antes."
L["|cffffd100Nearby|r -- about ten yards."] = "|cffffd100Cerca|r -- unos diez metros."
L["|cffffd100Right beside me|r -- about five yards."] = "|cffffd100Justo a mi lado|r -- unos cinco metros."
L["Only passers-by are measured; not somebody who buffed you, your group, or whoever you targeted or focused."] = "Solo se mide a los transeúntes; no a quien te dio un beneficio, a tu grupo ni a tu objetivo o tu foco."
L["The game gives no exact distance, so this is measured as closely as the client allows. When it cannot measure at all, everybody in casting range is offered."] = "El juego no da la distancia exacta, así que se mide con la precisión que permite el cliente. Cuando no puede medir nada, se ofrece a todos los que estén al alcance de tus hechizos."
L["Only offer passers-by in cities and inns"] = "Ofrecer a transeúntes solo en ciudades y posadas"
L["Out in the world, passers-by are left alone; they are offered only where the game shows you as resting, which is in a city or an inn."] = "Fuera, en el mundo, no se ofrece nada a los transeúntes; solo se les ofrece donde el juego te muestra descansando, es decir, en una ciudad o una posada."
L["Somebody who buffed you, your group, and whoever you have targeted or focused are offered anywhere."] = "A quien te dio un beneficio, a tu grupo y a tu objetivo o tu foco se les ofrece en cualquier lugar."
L["If the game will not say whether you are resting, passers-by are offered as usual."] = "Si el juego no dice si estás descansando, se ofrece a los transeúntes como siempre."
L["Drop people who are probably gone"] = "Descartar a quien seguramente se fue"
L["Somebody who buffed you can rarely be range-checked afterwards. With this on, they count as in range for a while after their buff, then are let go."] = "Rara vez se puede comprobar después la distancia de quien te dio un beneficio. Con esto activado, cuenta como al alcance durante un rato tras su beneficio, y luego se le descarta."
L["Let them go after (seconds)"] = "Descartarlos tras (segundos)"
L["How long somebody counts as in range after they buff you. It runs from their buff, not from when they walk off."] = "Cuánto tiempo cuenta alguien como al alcance después de darte un beneficio. Se cuenta desde su beneficio, no desde que se aleja."
L["Minimum level"] = "Nivel mínimo"
L["Players below this are never offered. Somebody known only by name cannot be level-checked and is offered anyway."] = "A los jugadores por debajo de este nivel nunca se les ofrece nada. A alguien de quien solo se sabe el nombre no se le puede comprobar el nivel y se le ofrece de todos modos."
L["Never offer"] = "No ofrecer nunca"
L["Nobody is on the list. Shift-right-click the prompt to put whoever it is showing on it, or add a name below."] = "No hay nadie en la lista. Haz Mayús + clic derecho en el aviso para añadir a quien esté mostrando, o añade un nombre abajo."
L["One person is on the list. They are never offered anything as a passer-by or as a member of your group."] = "Hay una persona en la lista. Nunca se le ofrece nada, ni como transeúnte ni como miembro de tu grupo."
L["%d people are on the list. They are never offered anything as passers-by or as members of your group."] = "Hay %d personas en la lista. Nunca se les ofrece nada, ni como transeúntes ni como miembros de tu grupo."
L["Somebody on it who buffs you is still offered the favour back. Shift-right-click them on the prompt to let that favour go."] = "Si alguien de la lista te da un beneficio, se te sigue ofreciendo devolverle el favor. Haz Mayús + clic derecho sobre esa persona en el aviso para descartar ese favor."
L["Add somebody by name"] = "Añadir a alguien por nombre"
L["Spelled the way the prompt shows them. Capitals do not matter."] = "Escríbelo como lo muestra el aviso. Las mayúsculas no importan."
L["On the list"] = "En la lista"
L["Take them off"] = "Quitar de la lista"
L["Clear the list"] = "Vaciar la lista"
L["Take everybody off the never-offer list?"] = "¿Quitar a todos de la lista de excluidos?"
L["General"] = "General"
L["Enable"] = "Activar"
L["Manners is switched off, so the prompt will never appear. Everything below is still saved."] = "Manners está desactivado, así que el aviso nunca aparecerá. Todo lo de abajo sigue guardado."
L["Your class has no buffs it can cast on another player."] = "Tu clase no tiene beneficios que pueda lanzar sobre otro jugador."
L["Manners has nothing to offer here. It is still worth keeping installed on an alt that does."] = "Manners no tiene nada que ofrecer aquí. Aun así, vale la pena tenerlo instalado para otro personaje que sí los tenga."
L["Manners could not work out what you can cast."] = "Manners no pudo averiguar qué puedes lanzar."
L["Either your class has nothing for other players, or the spell probe came back empty -- %s says which."] = "O tu clase no tiene nada para otros jugadores, o la detección de hechizos no devolvió nada -- %s te dice cuál de las dos."
L["How this works"] = "Cómo funciona"
L["Blizzard does not let an addon cast a spell by itself, so Manners works out who deserves a buff and puts them on the prompt. Click the prompt and it casts."] = "Blizzard no deja que un accesorio lance un hechizo por sí solo, así que Manners averigua quién merece un beneficio y pone su nombre en el aviso. Haz clic en el aviso y se lanza."
L["Putting it on a key"] = "Asignarlo a una tecla"
L["Make the macro below and drag it onto a bar, or bind a key under Options > Keybindings > Manners."] = "Crea la macro de abajo y arrástrala a una barra, o asigna una tecla en Opciones > Asignación de teclas > Manners."
L["Getting started"] = "Primeros pasos"
L["Create the macro"] = "Crear la macro"
L["Adds a macro called Manners containing %s. Drag it onto an action bar and it fires the prompt."] = "Añade una macro llamada Manners que contiene %s. Arrástrala a una barra de acción y activará el aviso."
L["Snooze"] = "Pausa"
L["|cffffd100Snoozed until %s.|r In a fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "|cffffd100En pausa hasta las %s.|r En combate, el aviso se queda como estaba al empezar el combate, y sigue la pausa cuando este termine."
L["|cffffd100Snoozed until %s.|r The prompt is unlocked, so it stays up to be dragged, casting nothing, until you lock it."] = "|cffffd100En pausa hasta las %s.|r El aviso está desbloqueado, así que sigue en pantalla para que lo arrastres, sin lanzar nada, hasta que lo bloquees."
L["|cffffd100Snoozed until %s.|r No prompt until then, though who buffs you is still noticed."] = "|cffffd100En pausa hasta las %s.|r No habrá aviso hasta entonces, aunque se sigue detectando quién te da un beneficio."
L["Keep the prompt out of the way for a while without switching Manners off. It comes back when the time is up, or after a %s."] = "Aparta el aviso durante un rato sin desactivar Manners. Vuelve cuando se acaba el tiempo, o después de un %s."
L["Stop snoozing"] = "Quitar la pausa"
L["Minimap"] = "Minimapa"
L["Show minimap button"] = "Mostrar botón del minimapa"
L["Manners stays in the addon compartment under the minimap either way."] = "Manners sigue en el compartimento de accesorios bajo el minimapa de todos modos."
L["Without it, |cffffd100/manners|r and the AddOns page in the game's options are the way in."] = "Sin él, puedes entrar con |cffffd100/manners|r o desde la página Accesorios de las opciones del juego."
L["Chat"] = "Chat"
L["Tell me in chat what the addon is doing"] = "Decirme en el chat qué hace el accesorio"
L["A line when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed."] = "Una línea cuando alguien te da un beneficio, cuando un favor se da por devuelto, y cuando un clic falla, se salta a alguien o deja un favor pendiente."
L["Only you see these lines. They tell a buff that was never noticed apart from somebody who could not be reached."] = "Solo tú ves estas líneas. Permiten distinguir un beneficio que nunca se detectó de alguien a quien no se pudo llegar."
L["Share settings"] = "Compartir configuración"
L["Copy these settings as one line of text, or paste one you were given."] = "Copia esta configuración como una línea de texto, o pega una que te hayan dado."
L["A paste leaves your on switch, lock, prompt position, click log and minimap button alone. It never switches on speaking, and while speaking is on, what you say and where stays yours."] = "Pegar no cambia si Manners está activado, el bloqueo, la posición del aviso, el registro de clics ni el botón del minimapa. Nunca activa Decir algo, y si lo tienes activado, lo que dices y dónde se queda como lo tienes."
L["Hide the text"] = "Ocultar el texto"
L["Show my settings as text"] = "Mostrar mi configuración como texto"
L["Shows these settings as one line of text in a box below, ready to select and copy. %s opens it too."] = "Muestra esta configuración como una línea de texto en un cuadro de abajo, lista para seleccionar y copiar. %s también lo abre."
L["Click in the box, press Ctrl+A to select it all, then Ctrl+C to copy (Cmd on a Mac)."] = "Haz clic en el cuadro, pulsa Ctrl+A para seleccionarlo todo y luego Ctrl+C para copiar (Cmd en Mac)."
L["Paste settings to use them"] = "Pegar una configuración para usarla"
L["Replaces the settings on this profile with the ones in the text. %s puts yours back."] = "Reemplaza la configuración de este perfil por la del texto. %s restaura la tuya."
L["Open the ledger"] = "Abrir el registro"
L["Who buffed you and with what, whether you returned it, and who you buffed unasked. Also %s, or shift-click the minimap button."] = "Quién te dio un beneficio y cuál, si se lo devolviste, y a quién le diste un beneficio por iniciativa propia. También con %s, o con Mayús + clic en el botón del minimapa."
L["Already buffed"] = "Ya tiene el beneficio"
L["If they already have the buff"] = "Si ya tiene el beneficio"
L["Reading whether somebody has a buff needs the game's permission. See the Diagnostics tab for which of your buffs qualify."] = "Saber si alguien tiene un beneficio requiere el permiso del juego. Mira la pestaña Diagnóstico para ver cuáles de tus beneficios lo permiten."
L["Somebody who buffed you is offered the favour back whichever you choose, even if they already have it."] = "Si alguien te dio un beneficio, se te ofrece devolverle el favor elijas lo que elijas, aunque ya lo tenga."
L["Leave them alone (unless they buffed you)"] = "No ofrecerle nada (salvo si te dio un beneficio)"
L["Offer a top-up when it is running out"] = "Ofrecer renovarlo cuando se esté acabando"
L["Always offer, whatever they have"] = "Ofrecer siempre, tenga lo que tenga"
L["Top up when under (minutes) are left"] = "Renovar cuando queden menos de (minutos)"
L["Only offer a refresh once their remaining time drops below this. Somebody whose timer cannot be read is left alone, unless they buffed you."] = "Solo ofrece renovarlo cuando el tiempo que le queda baja de este valor. A quien no se le puede leer la duración no se le ofrece nada, salvo si te dio un beneficio."
L["Everyone nearby will be offered constantly, including people whose buff has barely ticked down. Expect to be spending mana."] = "Se ofrecerá constantemente a todos los que estén cerca, incluso a quienes tienen el beneficio casi entero. Prepárate para gastar maná."
L["Nothing is read in this mode, so |cffffd100Whoever I have targeted comes first|r has no effect."] = "En este modo no se lee nada, así que |cffffd100Mi objetivo va primero|r no tiene efecto."
L["Timing"] = "Tiempos"
L["Remember a buff for (seconds)"] = "Recordar un beneficio durante (segundos)"
L["How long a favour is remembered. Somebody the game cannot see may be let go sooner by |cffffd100Drop people who are probably gone|r, under Who to buff."] = "Cuánto tiempo se recuerda un favor. A quien el juego no puede ver se le puede descartar antes con |cffffd100Descartar a quien seguramente se fue|r, en la pestaña A quién ofrecer."
L["Remember them across a reload"] = "Recordarlos tras una recarga"
L["Keep favours owed through a reload or a disconnect. The clock keeps running meanwhile, so a favour that ran out is not brought back."] = "Conserva los favores pendientes tras una recarga o una desconexión. El reloj sigue corriendo mientras tanto, así que no vuelve un favor cuyo tiempo se acabó."
L["Stored against this character, never shared between profiles. Switching it off deletes what has already been stored."] = "Se guarda para este personaje y nunca se comparte entre perfiles. Al desactivarlo se borra lo que ya estaba guardado."
L["Wait before offering the same spell again (seconds)"] = "Esperar antes de volver a ofrecer el mismo hechizo (segundos)"
L["After you click, how long before that spell is offered to that player again. Covers casts that failed out of sight."] = "Tras tu clic, cuánto tiempo pasa antes de volver a ofrecer ese hechizo a ese jugador. Cubre los lanzamientos que fallaron sin que lo vieras."
L["Per spell, not per person: after Fortitude the next scan can still offer them Divine Spirit. Right-clicking the prompt skips the whole person for this long."] = "Por hechizo, no por persona: tras Entereza, el siguiente escaneo aún puede ofrecerle Espíritu divino. Hacer clic derecho en el aviso salta a esa persona para todo durante este tiempo."
L["Scan every (seconds)"] = "Escanear cada (segundos)"
L["Lower is more responsive and slightly heavier."] = "Un valor más bajo responde más rápido y consume algo más."
L["Out of the way"] = "Sin estorbar"
L["Keep the prompt away while you are on a mount, since casting would take you off it. It comes back when you get off."] = "Oculta el aviso mientras vas montado, ya que lanzar te bajaría de la montura. Vuelve cuando desmontes."
L["It already stays away while you are dead, on a flight path or in a vehicle. In a fight the prompt stays as the fight found it until the fight ends."] = "Ya se oculta si mueres, vas en una ruta de vuelo o vas en un vehículo. En combate, el aviso se queda como estaba al empezar el combate hasta que este termine."
L["When you click"] = "Al hacer clic"
L["|cffffd100In combat.|r Blizzard freezes the prompt's macro during a fight, so these settings apply once it ends."] = "|cffffd100En combate.|r Blizzard congela la macro del aviso durante el combate, así que estas opciones se aplican cuando termine."
L["Targeting"] = "Selección de objetivo"
L["Hand my target back afterwards"] = "Recuperar mi objetivo después"
L["The prompt targets whoever it buffs, group members too. With this on, your previous target is restored right after the cast."] = "El aviso selecciona como objetivo a quien le da el beneficio, también a los miembros de tu grupo. Con esto activado, tu objetivo anterior se recupera justo después del lanzamiento."
L["Everything you can offer is cast on yourself and heard by your party, so the prompt never takes your target and has none to hand back."] = "Todo lo que puedes ofrecer se lanza sobre ti y lo oye tu grupo, así que el aviso nunca cambia tu objetivo y no hay nada que recuperar."
L["The prompt runs |cffffd100%s|r, the cast, then |cffffd100%s|r, except outside a fight for somebody already your target, who stays targeted."] = "El aviso ejecuta |cffffd100%s|r, el lanzamiento y luego |cffffd100%s|r, salvo fuera de combate con quien ya es tu objetivo, que sigue siéndolo."
L["The prompt runs |cffffd100%s|r, then the cast, and leaves them targeted."] = "El aviso ejecuta |cffffd100%s|r, luego el lanzamiento, y deja a esa persona como objetivo."
L["A %s conditional only reaches your party or raid, so the macro targets everybody it buffs."] = "Un condicional %s solo llega a tu grupo o banda, así que la macro selecciona como objetivo a cualquiera a quien dé un beneficio."
L["Speech"] = "Habla"
L["Say something when you buff somebody. The line is added to the macro the prompt runs, so it goes out as you talking rather than as an addon."] = "Di algo cuando le des un beneficio a alguien. La frase se añade a la macro que ejecuta el aviso, así que sale como si hablaras tú y no como un accesorio."
L["The game refuses addon-sent %s and %s outside instances, so going through the macro is what lets them work."] = "El juego rechaza %s y %s enviados por accesorios fuera de las instancias, así que ir a través de la macro es lo que permite que funcionen."
L["Say something"] = "Decir algo"
L["Channel"] = "Canal"
L["Say"] = "Decir"
L["Yell"] = "Gritar"
L["Party"] = "Grupo"
L["Raid"] = "Banda"
L["Emote"] = "Emoción"
L["Only when returning a favour"] = "Solo al devolver un favor"
L["Speak only when buffing somebody who buffed you first. Leave this on unless you want to announce every stranger you buff."] = "Habla solo al darle un beneficio a quien te lo dio primero. Déjalo activado salvo que quieras anunciar a cada desconocido al que le das un beneficio."
L["Phrases"] = "Frases"
L["Load a set"] = "Cargar un juego"
L["Replaces the lines below. Edit them afterwards as much as you like."] = "Reemplaza las frases de abajo. Luego edítalas tanto como quieras."
L["Replace everything in the box below with the %s lines?"] = "¿Reemplazar todo lo del cuadro de abajo por las frases de %s?"
L["loaded the %s lines."] = "se cargaron las frases de %s."
L["One per line -- a random one is picked each time the prompt changes target. Tokens: |cff888888{name}|r the player, |cff888888{buff}|r the spell."] = "Una por línea -- se elige una al azar cada vez que el aviso cambia de objetivo. Comodines: |cff888888{name}|r el jugador, |cff888888{buff}|r el hechizo."
L["A macro holds 255 characters, so a line that will not fit is dropped, not cut off -- |cffffd100Roll a few|r shows what would go out. An empty box goes back to the chosen set."] = "Una macro admite 255 caracteres, así que una frase que no quepa se deja fuera, no se corta -- |cffffd100Probar unas cuantas|r muestra lo que se enviaría. Un cuadro vacío vuelve al juego elegido."
L["In character: the line is picked when you click, to fit your race, your faction and the moment -- thanks for a favour, an answer to a request, or an offer. Below are a few of this character's lines; edit them and they become your own lines instead."] = "En personaje: la frase se elige al hacer clic, según tu raza, tu facción y el momento -- un agradecimiento por un favor, la respuesta a una petición o un ofrecimiento. Abajo tienes algunas frases de este personaje; si las editas, pasan a ser tus propias frases."
L["Roll a few"] = "Probar unas cuantas"
L["Somebody"] = "Alguien"
L["A line goes out when you click, even if the cast then fails out of range or line of sight."] = "La frase sale al hacer clic, aunque luego el lanzamiento falle por estar fuera de alcance o de línea de visión."
L["Prompt"] = "Aviso"
L["|cffffd100In combat.|r Blizzard freezes secure frames, so changes here are saved and appear once the fight ends."] = "|cffffd100En combate.|r Blizzard congela los marcos seguros, así que los cambios de aquí se guardan y aparecen cuando termine el combate."
L["Stop preview"] = "Parar la vista previa"
L["Preview"] = "Vista previa"
L["Show a sample entry to style the prompt by. It stays while this window is open, then twenty seconds more or until somebody real turns up."] = "Muestra una entrada de ejemplo para ajustar el aspecto del aviso. Se queda mientras esta ventana esté abierta y luego veinte segundos más, o hasta que aparezca alguien de verdad."
L["Locked"] = "Bloqueado"
L["Unlock to drag the prompt. It will not cast while unlocked."] = "Desbloquea para arrastrar el aviso. No lanzará nada mientras esté desbloqueado."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- switch it on first."] = "desbloqueado, pero el accesorio está |cffff8080desactivado|r, así que no hay aviso que arrastrar -- actívalo primero."
L["Reset position"] = "Restablecer posición"
L["Style"] = "Estilo"
L["Where the reason colour goes"] = "Dónde va el color del motivo"
L["A ring around the icon reads better than a stripe at the panel edge, which ends up competing with the icon rather than framing it."] = "Un anillo alrededor del icono se lee mejor que una franja en el borde del panel, que acaba compitiendo con el icono en lugar de enmarcarlo."
L["The framed look has no stripe at all -- it would run down the inside of its border -- so on it the stripe settings do nothing."] = "El aspecto Enmarcado no tiene franja -- recorrería el interior de su borde -- así que con él las opciones de la franja no hacen nada."
L["Ring around the icon"] = "Anillo alrededor del icono"
L["Stripe down the left edge"] = "Franja en el borde izquierdo"
L["Both"] = "Ambos"
L["Neither"] = "Ninguno"
L["Colour it by reason"] = "Colorear según el motivo"
L["Pale yellow for your own target, orange for a favour owed, deep pink for somebody who asked, sky blue for your group, violet for passers-by -- the order they are offered in."] = "Amarillo claro para tu propio objetivo, naranja para un favor pendiente, rosa intenso para quien lo pidió, azul cielo para tu grupo, violeta para los transeúntes -- el orden en que se ofrecen."
L["Pale blue for your own target, amber for a favour owed, pink for somebody who asked, deeper blue for your group, grey for passers-by -- the order they are offered in."] = "Azul claro para tu propio objetivo, ámbar para un favor pendiente, rosa para quien lo pidió, azul más intenso para tu grupo, gris para los transeúntes -- el orden en que se ofrecen."
L["The first of those appears only while |cffffd100Whoever I have targeted comes first|r is on and |cffffd100If they already have the buff|r is not Always offer."] = "El primero de esos colores solo aparece mientras |cffffd100Mi objetivo va primero|r esté activado y |cffffd100Si ya tiene el beneficio|r no esté en Ofrecer siempre."
L["Reason colours"] = "Colores de los motivos"
L["The colour-blind set keeps the reasons apart for red-green colour blindness, in colours that differ in lightness too."] = "La paleta para daltónicos mantiene distinguibles los motivos con daltonismo rojo-verde, con colores que también difieren en luminosidad."
L["Standard"] = "Estándar"
L["Colour-blind friendly"] = "Para daltónicos"
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off, and the framed look has no stripe."] = "No queda nada que colorear: el anillo se dibuja detrás del icono, que está desactivado, y el aspecto Enmarcado no tiene franja."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask, and the framed look has no stripe."] = "No queda nada que colorear: redondear el icono sustituye el anillo por una máscara, y el aspecto Enmarcado no tiene franja."
L["There is nothing left to colour: the ring is drawn behind the icon, which is switched off."] = "No queda nada que colorear: el anillo se dibuja detrás del icono, que está desactivado."
L["There is nothing left to colour: rounding the icon off replaces the ring with a mask."] = "No queda nada que colorear: redondear el icono sustituye el anillo por una máscara."
L["There is nothing left to colour: the framed look has no stripe."] = "No queda nada que colorear: el aspecto Enmarcado no tiene franja."
L["Accent colour"] = "Color de acento"
L["Used for the ring, the stripe, or both -- whichever the setting above asks for."] = "Se usa para el anillo, la franja o ambos -- lo que pida la opción de arriba."
L["Look"] = "Aspecto"
L["Glass -- dark panel, soft shadow"] = "Cristal -- panel oscuro, sombra suave"
L["Framed -- flat panel, thin border"] = "Enmarcado -- panel plano, borde fino"
L["Minimal -- text only, no panel"] = "Mínimo -- solo texto, sin panel"
L["Panel colour"] = "Color del panel"
L["Getting your attention"] = "Llamar tu atención"
L["When someone buffs you"] = "Cuando alguien te da un beneficio"
L["Pulse keeps breathing until you have returned the favour or they are gone. Flash once is easy to miss if you were looking elsewhere."] = "Latir sigue palpitando hasta que devuelvas el favor o esa persona se vaya. Destellar una vez es fácil de pasar por alto si mirabas a otro lado."
L["It lights the spell icon, sweeps the stripe, and with Effects on Full the panel catches the light. With none of those showing it has nothing to do."] = "Ilumina el icono del hechizo, recorre la franja y, con Efectos en Completo, hace brillar el panel. Si no se muestra nada de eso, no le queda nada que hacer."
L["Pulse until dealt with"] = "Latir hasta atenderlo"
L["Flash once"] = "Destellar una vez"
L["Nothing"] = "Nada"
L["Effects"] = "Efectos"
L["Full: light crosses the panel when a buff lands, a refused buff shakes the text, and the prompt fades out after your last buff."] = "Completo: una luz cruza el panel cuando se aplica un beneficio, un beneficio rechazado hace temblar el texto, y el aviso se desvanece tras tu último beneficio."
L["Calm: none of that movement. The prompt still fades in, and the glow set above still works."] = "Tranquilo: nada de ese movimiento. El aviso sigue apareciendo poco a poco, y el brillo elegido arriba sigue funcionando."
L["The Minimal look has no panel, so no light crosses it. In a fight, Stay quiet in combat keeps the outcome still as well."] = "El aspecto Mínimo no tiene panel, así que ninguna luz lo cruza. En combate, Discreto en combate también quita el movimiento del resultado de cada clic."
L["Full"] = "Completo"
L["Calm -- less movement"] = "Tranquilo -- menos movimiento"
L["Play a sound"] = "Reproducir un sonido"
L["Play a sound when somebody new reaches the top of the queue."] = "Reproduce un sonido cuando alguien nuevo llega al primer puesto de la cola."
L["Sound"] = "Sonido"
L["%s |cff808080(not loaded)|r"] = "%s |cff808080(no cargado)|r"
L["Only when somebody buffed me"] = "Solo si alguien me dio un beneficio"
L["Off, every new person on the prompt makes a noise -- including strangers you happen to walk past."] = "Si lo desactivas, suena con cada persona nueva en el aviso -- incluso con desconocidos junto a los que pasas por casualidad."
L["%s is silent. Pick a sound above."] = "%s no tiene sonido. Elige un sonido arriba."
L["Position and size"] = "Posición y tamaño"
L["Put it"] = "Colocarlo"
L["Three places that are already right. Dragging the prompt afterwards leaves this blank, because it is then not on one of them."] = "Tres sitios que ya quedan bien. Si después arrastras el aviso, esto se queda en blanco, porque ya no está en ninguno de ellos."
L["X offset"] = "Desplazamiento X"
L["Y offset"] = "Desplazamiento Y"
L["Width"] = "Ancho"
L["Height"] = "Alto"
L["Scale"] = "Escala"
L["Opacity"] = "Opacidad"
L["Stay quiet in combat"] = "Discreto en combate"
L["A click still casts in combat, and the prompt flashes to say what happened -- red if it failed. With this on it stays dimmed and still for the fight."] = "En combate, un clic sigue lanzando, y el aviso destella para indicar qué pasó -- en rojo si falló. Con esto activado, se queda atenuado y quieto mientras dure el combate."
L["It stays on screen in a fight on purpose: your key binding would still cast the frozen macro if it were hidden."] = "Se queda en pantalla en combate a propósito: si estuviera oculto, tu tecla asignada seguiría lanzando la macro congelada."
L["Text"] = "Texto"
L["First line"] = "Primera línea"
L["Tokens: {name} {reason} {count} {class} {buff} {time}"] = "Comodines: {name} {reason} {count} {class} {buff} {time}"
L["Show a second line"] = "Mostrar una segunda línea"
L["Needs a prompt at least %d pixels tall at this font size."] = "Necesita un aviso de al menos %d píxeles de alto con este tamaño de fuente."
L["|cff888888{name}|r who   |cff888888{reason}|r why   |cff888888{count}|r how many more   |cff888888{class}|r their class   |cff888888{buff}|r the spell"] = "|cff888888{name}|r quién   |cff888888{reason}|r por qué   |cff888888{count}|r cuántos más   |cff888888{class}|r su clase   |cff888888{buff}|r el hechizo"
L["|cff888888{time}|r what theirs has left, on a top-up and nowhere else"] = "|cff888888{time}|r cuánto le queda al suyo, solo en una renovación"
L["The second line always shows the reason."] = "La segunda línea siempre muestra el motivo."
L["Wording: your target"] = "Texto: tu objetivo"
L["Your target outranks everyone, including a favour owed, while that is switched on under Who to buff and the game can see they lack it."] = "Tu objetivo va por delante de todos, incluso de un favor pendiente, mientras esa opción esté activada en la pestaña A quién ofrecer y el juego pueda ver que le falta."
L["Wording: buffed you"] = "Texto: te dio un beneficio"
L["Wording: in your group"] = "Texto: en tu grupo"
L["Wording: nearby"] = "Texto: cerca"
L["Wording: topping one up"] = "Texto: renovación"
L["Used instead of the four above when their buff is about to run out, which only the refresh mode offers. |cffffd100{time}|r is how long theirs has left."] = "Se usa en lugar de los cuatro de arriba cuando su beneficio está a punto de acabarse, algo que solo ofrece el modo de renovación. |cffffd100{time}|r es cuánto le queda al suyo."
L["Wording: state unknown"] = "Texto: estado desconocido"
L["Used when the game will not let addons read whether they already have it."] = "Se usa cuando el juego no deja a los accesorios saber si ya lo tiene."
L["Font"] = "Fuente"
L["Font size"] = "Tamaño de fuente"
L["Text colour"] = "Color del texto"
L["Left at white, text turns dark on a light panel by itself. Other colours are used as picked, except for names while |cffffd100Colour names by class|r is on."] = "Si mantienes el blanco, el texto se vuelve oscuro por sí solo sobre un panel claro. Los demás colores se usan tal como los eliges, salvo en los nombres mientras |cffffd100Colorear nombres según la clase|r esté activado."
L["Colour names by class"] = "Colorear nombres según la clase"
L["Icon and queue"] = "Icono y cola"
L["Show spell icon"] = "Mostrar icono del hechizo"
L["Icon size"] = "Tamaño del icono"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "Se mantiene dentro del aviso -- para un icono más grande, hazlo antes más alto o más ancho."
L["The icon is held at %d to fit a prompt %d wide."] = "El icono se limita a %d para caber en un aviso de %d de ancho."
L["The icon is held at %d to fit a prompt %d high."] = "El icono se limita a %d para caber en un aviso de %d de alto."
L["Round the icon off"] = "Redondear el icono"
L["Masks the icon into a circle. Reads more like a portrait than a spell, so it is off by default."] = "Recorta el icono en un círculo. Parece más un retrato que un hechizo, así que viene desactivado de forma predeterminada."
L["The mask replaces the ring, so move the reason colour to the stripe if you want both. The glow when somebody buffs you follows the circle."] = "La máscara sustituye al anillo, así que pasa el color del motivo a la franja si quieres ambos. El brillo cuando alguien te da un beneficio sigue el círculo."
L["Show the global cooldown on the icon"] = "Mostrar el tiempo de reutilización global en el icono"
L["Sweeps the spell icon while the global cooldown runs, like your action bars, so you can see when the next press will go through."] = "Hace un barrido sobre el icono del hechizo mientras corre el tiempo de reutilización global, como en tus barras de acción, para que veas cuándo funcionará la siguiente pulsación."
L["Not in a fight while Stay quiet in combat is on."] = "No en combate mientras Discreto en combate esté activado."
L["Show how many are waiting"] = "Mostrar cuántos esperan"
L["List the next few below"] = "Mostrar los siguientes debajo"
L["How many to list"] = "Cuántos mostrar"
L["Diagnostics"] = "Diagnóstico"
L["Log every click to chat"] = "Registrar cada clic en el chat"
L["Prints what the button held when you clicked and what the game did with it. Noisy; for working out why a cast did not happen."] = "Muestra qué tenía el botón al hacer clic y qué hizo el juego con ello. Llena el chat; sirve para averiguar por qué no se lanzó un hechizo."
L["What this client allows"] = "Qué permite este cliente"
L["Class: |cffffffff%s|r"] = "Clase: |cffffffff%s|r"
L["learned: |cff00ff00yes|r"] = "aprendido: |cff00ff00sí|r"
L["learned: |cff808080no|r"] = "aprendido: |cff808080no|r"
L["missing-check: |cff00ff00works|r"] = "comprobación de ausencia: |cff00ff00funciona|r"
L["missing-check: |cffff8080blocked|r"] = "comprobación de ausencia: |cffff8080bloqueada|r"
L["this client has never heard of spell %s, so Manners will never offer this one. That is a mistake in Manners -- please report it."] = "este cliente no reconoce el hechizo %s, así que Manners nunca ofrecerá este beneficio. Es un error de Manners -- por favor, repórtalo."
L["this client doesn't know spell %s, so somebody already carrying that version may be offered this anyway. That is a mistake in Manners -- please report it."] = "este cliente no conoce el hechizo %s, así que puede que se ofrezca este beneficio igualmente a alguien que ya lleva esa versión. Es un error de Manners -- por favor, repórtalo."
L["Where the missing-check is blocked, addons cannot read that aura: players are still offered, but some may already have the buff."] = "Donde la comprobación de ausencia está bloqueada, los accesorios no pueden leer esa aura: se sigue ofreciendo a los jugadores, pero puede que algunos ya tengan el beneficio."
L["Nothing to report: this character has no buffs it can put on another player."] = "Nada que informar: este personaje no tiene beneficios que pueda dar a otro jugador."
L["What has broken"] = "Qué falló"
L["(%d in all this session, %d kept -- |cffffd100%s|r)"] = "(%d en total esta sesión, %d guardados -- |cffffd100%s|r)"
L["(%d in all this session -- |cffffd100%s|r)"] = "(%d en total esta sesión -- |cffffd100%s|r)"
L["Nothing has broken this session."] = "Nada falló en esta sesión."
L["Reporting a bug"] = "Reportar un error"
L["Hide the report"] = "Ocultar el informe"
L["Copy for a bug report"] = "Copiar para reportar un error"
L["Opens a box with the build, what this client allows, the settings that matter and anything that has broken, ready to copy."] = "Abre un cuadro con la versión de Manners, lo que permite este cliente, las opciones importantes y todo lo que haya fallado, listo para copiar."
L["Switched off -- the prompt this fight froze stays up until it ends, and a press still casts it."] = "Desactivado -- el aviso que congeló el combate sigue en pantalla hasta que este termine, y una pulsación aún lanza su hechizo."
L["Switched off -- no prompt will appear."] = "Desactivado -- no aparecerá ningún aviso."
L["Unlocked, but in this fight the prompt stays as the fight found it, and a press still casts it; it can be dragged once the fight ends."] = "Desbloqueado, pero en este combate el aviso se queda como estaba al empezar, y una pulsación aún lanza su hechizo; se podrá arrastrar cuando termine el combate."
L["Unlocked -- the prompt this fight froze stays up until it ends, and a press still casts it; then it can be dragged."] = "Desbloqueado -- el aviso que congeló el combate sigue en pantalla hasta que este termine, y una pulsación aún lanza su hechizo; después se podrá arrastrar."
L["Unlocked, and snoozed until %s -- the prompt stays up to be dragged, casting nothing, until you lock it."] = "Desbloqueado y en pausa hasta las %s -- el aviso sigue en pantalla para que lo arrastres, sin lanzar nada, hasta que lo bloquees."
L["Unlocked -- the prompt is up to be dragged and casts nothing until you lock it (%s)."] = "Desbloqueado -- el aviso está en pantalla para que lo arrastres y no lanza nada hasta que lo bloquees (%s)."
L["Snoozed until %s -- in this fight the prompt stays as the fight found it, and follows the snooze once the fight ends."] = "En pausa hasta las %s -- en este combate el aviso se queda como estaba al empezar, y sigue la pausa cuando este termine."
L["Snoozed until %s, %s from now -- no prompt until then."] = "En pausa hasta las %s, dentro de %s -- sin avisos hasta entonces."
L["Nothing to do: %s"] = "Nada que hacer: %s"
L["Nothing to cast on this character -- /manners debug says why."] = "Nada que lanzar con este personaje -- /manners debug te dice por qué."
L["Nothing will be offered: %s."] = "No se ofrecerá nada: %s."
L["Nothing learned to cast yet."] = "Aún no aprendiste nada que lanzar."
L["Kept away while you are mounted -- %s, on the %s tab."] = "Oculto mientras vas montado -- %s, en la pestaña %s."
L["Watching for people to buff."] = "Buscando a quién dar un beneficio."
L["Held in combat -- the prompt moves on once the fight ends."] = "Retenido en combate -- el aviso avanzará cuando termine el combate."
