L["Next: |cffffffff%s|r -- %s, asked for it"] = "Siguiente: |cffffffff%s|r -- %s, lo pidió"
L["Left click: options"] = "Clic izquierdo: opciones"
L["Shift-click: favour ledger"] = "Mayús + clic: registro de favores"
